"""Generate two original tones. No third-party music or licensing assumptions."""
from pathlib import Path
import json, math, struct, wave
import sys

stack = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(stack / "scripts"))
from runtime_path import runtime_dir

root = runtime_dir(stack) / "fixtures"
root.mkdir(parents=True, exist_ok=True)
records={}
for ident,hz,title in [('one',220,'Luz de prueba'),('two',330,'Noche de prueba')]:
    file=root/(ident+'.wav')
    with wave.open(str(file),'wb') as out:
        out.setnchannels(1);out.setsampwidth(2);out.setframerate(16000)
        out.writeframes(b''.join(struct.pack('<h',int(1500*math.sin(2*math.pi*hz*i/16000))) for i in range(16000*34)))
    records['authorized_http:'+ident]={'authorization':'Original synthetic tone generated by tests/fixtures/prepare_audio.py; all uses in this laboratory authorized',
        'stream':True,'offline':True,'persist':True,'cache':True,'url':f'http://fixtures:8100/{ident}.wav',
        'metadata':{'title':title,'artist':'Artista sintético' if ident=='one' else 'Artista segundo','album':'Pruebas','duration':34,
                    'artist_mbids':['11111111-1111-4111-8111-111111111111' if ident=='one' else '22222222-2222-4222-8222-222222222222']}}
for ident, original, user, number in [('three','one','Alice','3'),('four','two','Bob','4')]:
    records['authorized_http:'+ident] = {**records['authorized_http:'+original], 'metadata': {
        'title':'Estreno '+user,'artist':'Descubrimiento '+user,'album':'Pruebas','duration':34,
        'artist_mbids':[number*8+'-'+number*4+'-4'+number*3+'-8'+number*3+'-'+number*12]}}
(root/'sources.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))
print('Two original synthetic audio fixtures generated.')
